#!/usr/bin/env node
// Kilowott brand kit — token build.
// Source of truth: project/styles/tokens.css. Everything below is generated from it.
//
//   npm run build:tokens          write every generated file
//   node scripts/build-tokens.mjs --dry   list what would change, write nothing
//
// Generated outputs (do not edit by hand):
//   tokens.json                         W3C design-tokens format (light + dark + state + semantic)
//   project/brand.json  → "tokens" key  CSS-free summary (rest of brand.json is hand-written)
//   <!-- tokens:start --> blocks in llms.txt, project/llms.txt, KILOWOTT_BRAND.md, AGENTS.md
//   llms-full.txt                       AGENTS.md + KILOWOTT_BRAND.md + project/llms.txt
//   project/kit/kilowott.css            drop-in stylesheet (fonts + tokens + base + primitives)
//   project/kit/tokens.scss             Sass variables + maps
//   project/kit/tokens.tailwind.js      Tailwind v3 preset
//   project/kit/tokens.tailwind.css     Tailwind v4 @theme block
//   project/kit/figma-tokens.json       Tokens Studio for Figma
//   project/downloads/kilowott-colors.{ase,gpl,json}, project/downloads/kilowott-logo.svg
//
// No dependencies. Node >= 18.

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import {
  parseTokensCss, makeResolver, refOf, hexToRgb, normHex, contrast, isHex,
  parseShadow, parseFontStack, remToPx, clampPx,
} from './lib/tokens.mjs';

export const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
export const BASE_URL = 'https://brandkit.kilowott.com';
export const GOOGLE_FONTS =
  'https://fonts.googleapis.com/css2?family=Newsreader:ital,opsz,wght@0,6..72,400;0,6..72,500;1,6..72,400;1,6..72,500&family=DM+Sans:wght@400;500&family=JetBrains+Mono:wght@400;500&display=swap';
export const LUCIDE_CDN = 'https://unpkg.com/lucide@1.66.0/dist/umd/lucide.min.js';

const GEN_NOTE = 'Generated by scripts/build-tokens.mjs from project/styles/tokens.css. Do not edit by hand: run `npm run build:tokens`.';

const SEMANTIC_ROLES = {
  bg: 'page background',
  'bg-2': 'warm paper: section breaks, cards on paper',
  'bg-3': 'warmer card on paper',
  fg: 'primary text',
  'fg-2': 'secondary text',
  accent: 'signature red: one spotlight per surface',
  'accent-ink': 'red for small text on paper',
  'accent-hover': 'hover / pressed state for red fills',
  rule: 'soft divider',
  'rule-strong': 'strong rule / button border',
  link: 'text links, inline code, small red text',
  logo: 'the wordmark: navy on paper, white on ink',
  success: 'state: success (product UI only)',
  'success-soft': 'state: success tint',
  warning: 'state: warning (product UI only)',
  'warning-soft': 'state: warning tint',
  info: 'state: info (product UI only)',
  'info-soft': 'state: info tint',
  danger: 'state: danger = brand red',
  'danger-soft': 'state: danger tint',
};

const CONTRAST_PAIRS = [
  ['--k-ink', '--k-paper'], ['--k-ink-2', '--k-paper'], ['--k-muted', '--k-paper'], ['--k-muted', '--k-paper-2'],
  ['--k-red', '--k-paper'], ['--k-red', '--k-paper-2'], ['--k-red-ink', '--k-paper'], ['--k-red-ink', '--k-paper-2'],
  ['--k-paper', '--k-red'], ['--k-paper', '--k-ink'], ['--k-muted-dark', '--k-ink'], ['--k-red', '--k-ink'],
  ['--k-red-soft', '--k-ink'], ['--k-success', '--k-paper'], ['--k-warning', '--k-paper'], ['--k-info', '--k-paper'],
  ['--k-success', '--k-paper-2'], ['--k-warning', '--k-paper-2'], ['--k-info', '--k-paper-2'],
];

const read = rel => fs.readFileSync(path.join(ROOT, rel), 'utf8');

// ============================================================
// MODEL
// ============================================================
export function loadModel() {
  const css = read('project/styles/tokens.css');
  const { root, dark } = parseTokensCss(css);
  const light = makeResolver(root);
  const darkR = makeResolver(root, dark);
  const pkg = JSON.parse(read('package.json'));
  const version = pkg.version.split('.').slice(0, 2).join('.');

  const classify = d => {
    const n = d.name.slice(2);
    switch (d.group) {
      case 'brand': return { path: ['color', 'brand', n.replace(/^k-/, '')], type: 'color' };
      case 'state': return { path: ['color', 'state', n.replace(/^k-/, '')], type: 'color' };
      case 'semantic': return { path: ['color', 'semantic', n], type: 'color' };
      case 'type':
        if (n.startsWith('font-')) return { path: ['typography', 'fontFamily', n.slice(5)], type: 'fontFamily' };
        if (n.startsWith('fs-')) return { path: ['typography', 'fontSize', n.slice(3)], type: 'dimension' };
        if (n.startsWith('lh-')) return { path: ['typography', 'lineHeight', n.slice(3)], type: 'number' };
        if (n.startsWith('tracking-')) return { path: ['typography', 'letterSpacing', n.slice(9)], type: 'dimension' };
        break;
      case 'spacing': return { path: ['spacing', n.replace(/^s-/, '')], type: 'dimension' };
      case 'radii': return { path: ['radius', n.replace(/^r-/, '')], type: 'dimension' };
      case 'shadow': return { path: ['shadow', n.replace(/^shadow-/, '')], type: 'shadow' };
      case 'motion':
        if (n.startsWith('ease-')) return { path: ['motion', 'easing', n.slice(5)], type: 'cubicBezier' };
        if (n.startsWith('dur-')) return { path: ['motion', 'duration', n.slice(4)], type: 'duration' };
        break;
      case 'layout': return { path: ['layout', n], type: 'dimension' };
    }
    throw new Error(`tokens.css: cannot classify ${d.name} (section: ${d.group})`);
  };

  root.forEach(d => Object.assign(d, classify(d)));
  dark.forEach(d => {
    const base = root.find(r => r.name === d.name);
    Object.assign(d, base ? { path: base.path, type: base.type } : classify(d));
    if (base && !d.comment) d.comment = null;
  });

  const by = g => root.filter(d => d.group === g);
  return {
    css, root, dark, light, darkR, version,
    brand: by('brand'), state: by('state'), semantic: by('semantic'),
    type: by('type'), spacing: by('spacing'), radii: by('radii'),
    shadow: by('shadow'), motion: by('motion'), layout: by('layout'),
    pathOf: Object.fromEntries(root.map(d => [d.name, d.path.join('.')])),
    describe: d => {
      if (d.group === 'state') {
        const [, kind, soft] = /^--k-(\w+)(-soft)?$/.exec(d.name) || [];
        const base = soft ? `${kind} tint (badge / banner background)` : `${kind} text, icons, dots`;
        return d.comment ? `${base} · ${d.comment}` : base;
      }
      return d.comment || d.note || SEMANTIC_ROLES[d.name.slice(2)] || null;
    },
  };
}

// ============================================================
// tokens.json (W3C design tokens)
// ============================================================
function setPath(obj, p, val) {
  let o = obj;
  p.slice(0, -1).forEach(k => { o = o[k] = o[k] || {}; });
  o[p[p.length - 1]] = val;
}

function dtcgValue(d, M) {
  const ref = refOf(d.value);
  if (ref && M.pathOf[ref]) return `{${M.pathOf[ref]}}`;
  switch (d.type) {
    case 'color': return isHex(d.value) ? normHex(d.value) : d.value;
    case 'fontFamily': return parseFontStack(d.value);
    case 'dimension': return d.value === '0' ? '0px' : d.value;
    case 'number': return parseFloat(d.value);
    case 'shadow': {
      const layers = parseShadow(d.value);
      return layers.length ? layers : [{ color: '#00000000', offsetX: '0px', offsetY: '0px', blur: '0px', spread: '0px' }];
    }
    case 'cubicBezier': return (d.value.match(/[-\d.]+/g) || []).map(Number);
    default: return d.value;
  }
}

function dtcgToken(d, M, resolver) {
  const t = { $type: d.type, $value: dtcgValue(d, M) };
  const desc = M.describe(d);
  if (desc) t.$description = desc;
  const ext = { cssVar: d.name };
  if (d.type === 'color') { const r = resolver.get(d.name); if (r !== d.value || refOf(d.value)) ext.resolved = isHex(r) ? normHex(r) : r; }
  if (d.type === 'dimension' && /clamp/.test(d.value)) { const px = clampPx(d.value); if (px) ext.pxRange = px; }
  if (d.type === 'dimension' && remToPx(d.value) !== null) ext.px = remToPx(d.value);
  if (d.type === 'shadow') ext.css = d.value;
  t.$extensions = { 'com.kilowott': ext };
  return t;
}

function buildTokensJson(M) {
  const out = {
    $description: `Kilowott brand kit v${M.version}: design tokens in W3C Design Tokens (DTCG) format. ${GEN_NOTE}`,
    $extensions: {
      'com.kilowott': {
        name: 'Kilowott Design System',
        version: M.version,
        source: `${BASE_URL}/project/styles/tokens.css`,
        docs: `${BASE_URL}/AGENTS.md`,
        themes: { default: 'light', dark: 'apply [data-theme="dark"] on <html>; overrides live under theme.dark' },
        usageRatio: { paper: 60, ink: 30, warm: 5, red: 5, rule: '60·30·5·5 = paper · ink · warm paper · red' },
        googleFonts: GOOGLE_FONTS,
        icons: { library: 'Lucide', version: '1.66.0', cdn: LUCIDE_CDN, strokeWidth: 1.5, color: 'currentColor' },
      },
    },
  };
  M.root.forEach(d => setPath(out, d.path, dtcgToken(d, M, M.light)));
  M.dark.forEach(d => {
    const t = dtcgToken(d, M, M.darkR);
    t.$description = `[data-theme="dark"] override of ${d.name}` + (M.describe(d) ? ` — ${M.describe(d)}` : '');
    setPath(out, ['theme', 'dark', ...d.path], t);
  });
  return JSON.stringify(out, null, 2) + '\n';
}

// ============================================================
// brand.json "tokens" summary (CSS-free, resolved values)
// ============================================================
const shortName = n => n.replace(/^--(k-)?/, '');

function contrastRows(M) {
  return CONTRAST_PAIRS.map(([fg, bg]) => {
    const a = M.light.get(fg), b = M.light.get(bg);
    const r = contrast(a, b);
    return { fg: fg, bg: bg, fg_hex: normHex(a), bg_hex: normHex(b), ratio: Math.round(r * 100) / 100, body_aa: r >= 4.5, large_aa: r >= 3 };
  });
}

function buildBrandTokens(M) {
  const colorEntry = d => {
    const hex = normHex(M.light.get(d.name));
    return { hex, rgb: hexToRgb(hex), css_var: d.name, role: M.describe(d) };
  };
  const semantic = theme => Object.fromEntries(M.semantic.map(d => {
    const R = theme === 'dark' ? M.darkR : M.light;
    const raw = R.raw(d.name);
    const resolved = R.get(d.name);
    const e = { css_var: d.name, value: isHex(resolved) ? normHex(resolved) : resolved };
    const ref = refOf(raw);
    if (ref) e.maps_to = ref;
    if (theme === 'light') e.use = SEMANTIC_ROLES[shortName(d.name)] || M.describe(d);
    return [shortName(d.name), e];
  }));
  const scale = Object.fromEntries(M.type.filter(d => d.name.startsWith('--fs-')).map(d => {
    const e = { css_var: d.name, css: d.value };
    const range = clampPx(d.value); if (range) e.px_range = range;
    const px = remToPx(d.value); if (px !== null) e.px = px;
    if (d.comment) e.note = d.comment;
    return [shortName(d.name).replace(/^fs-/, ''), e];
  }));
  const simple = (list, strip) => Object.fromEntries(list.map(d => [shortName(d.name).replace(strip, ''), d.value]));
  return {
    _generated: GEN_NOTE,
    colors: {
      brand: Object.fromEntries(M.brand.map(d => [shortName(d.name), colorEntry(d)])),
      state: Object.fromEntries(M.state.map(d => [shortName(d.name), colorEntry(d)])),
    },
    semantic: { light: semantic('light'), dark: semantic('dark') },
    contrast: contrastRows(M),
    typography: {
      families: Object.fromEntries(M.type.filter(d => d.name.startsWith('--font-')).map(d =>
        [shortName(d.name).replace(/^font-/, ''), { css_var: d.name, stack: parseFontStack(d.value) }])),
      google_fonts_url: GOOGLE_FONTS,
      scale,
      line_height: Object.fromEntries(M.type.filter(d => d.name.startsWith('--lh-')).map(d => [shortName(d.name).slice(3), parseFloat(d.value)])),
      tracking: simple(M.type.filter(d => d.name.startsWith('--tracking-')), /^tracking-/),
    },
    spacing: Object.fromEntries(M.spacing.map(d => [shortName(d.name), d.value === '0' ? '0px' : d.value])),
    radii: simple(M.radii, /^$/),
    shadows: {
      light: simple(M.shadow, /^shadow-/),
      dark: Object.fromEntries(M.dark.filter(d => d.group === 'shadow').map(d => [shortName(d.name).replace(/^shadow-/, ''), d.value])),
    },
    motion: simple(M.motion, /^$/),
    layout: simple(M.layout, /^$/),
  };
}

function buildBrandJson(M) {
  const current = JSON.parse(read('project/brand.json'));
  current.version = M.version;
  current.tokens = buildBrandTokens(M);
  return JSON.stringify(current, null, 2) + '\n';
}

// ============================================================
// Markdown token tables
// ============================================================
const code = s => '`' + String(s).replace(/\|/g, '\\|') + '`';

function mdColorTable(M, list) {
  return ['| Token | Hex | Role |', '|---|---|---|',
    ...list.map(d => `| ${code(d.name)} | ${code(normHex(M.light.get(d.name)))} | ${(M.describe(d) || '').replace(/\|/g, '/')} |`)].join('\n');
}

function mdSemanticTable(M) {
  const cell = (R, n) => {
    const raw = R.raw(n), res = R.get(n);
    const val = isHex(res) ? normHex(res) : res;
    const ref = refOf(raw);
    return ref ? `${code(val)} (${code(ref)})` : code(val);
  };
  return ['| Token | Light (default) | Dark (`[data-theme="dark"]`) | Use for |', '|---|---|---|---|',
    ...M.semantic.map(d => `| ${code(d.name)} | ${cell(M.light, d.name)} | ${cell(M.darkR, d.name)} | ${SEMANTIC_ROLES[shortName(d.name)] || ''} |`)].join('\n');
}

function mdContrast(M) {
  return ['| Foreground | Background | Ratio | Body text (4.5:1) | Large text (3:1) |', '|---|---|---|---|---|',
    ...contrastRows(M).map(r => `| ${code(r.fg)} ${r.fg_hex} | ${code(r.bg)} ${r.bg_hex} | ${r.ratio.toFixed(2)}:1 | ${r.body_aa ? 'pass' : 'fail'} | ${r.large_aa ? 'pass' : 'fail'} |`)].join('\n');
}

function mdTokensBlock(M, variant) {
  const inline = list => list.map(d => `${code(d.name)} ${d.value}`).join(' · ');
  const parts = [
    `<!-- ${GEN_NOTE} -->`, '',
    '### Brand colours', '', mdColorTable(M, M.brand), '',
    '### State colours (product UI only, never marketing)', '', mdColorTable(M, M.state), '',
    '### Semantic tokens (use these in CSS; they switch with the theme)', '', mdSemanticTable(M), '',
  ];
  if (variant === 'compact') {
    parts.push(
      `**Fonts:** ${inline(M.type.filter(d => d.name.startsWith('--font-')))}`, '',
      `**Spacing (8pt):** ${inline(M.spacing)}`, '',
      `**Radii:** ${inline(M.radii)}`, '',
      `Full tables (type scale, shadows, motion, contrast): ${BASE_URL}/KILOWOTT_BRAND.md#2-tokens`, '');
  } else {
    parts.push(
      '### Contrast (WCAG 2.2, computed from the hex values)', '', mdContrast(M), '',
      '### Type', '',
      '| Token | Value | Note |', '|---|---|---|',
      ...M.type.map(d => {
        const range = clampPx(d.value), px = remToPx(d.value);
        const note = range ? `${range[0]}–${range[1]}px fluid` : px !== null ? `${px}px` : (d.comment || '');
        return `| ${code(d.name)} | ${code(d.value)} | ${note}${d.comment && (range || px !== null) ? ' · ' + d.comment.replace(/^[\d–\s]+(—\s*)?/, '') : ''} |`.replace(/ · \s*\|$/, ' |');
      }), '',
      '### Spacing, radii, elevation, motion, layout', '',
      `- **Spacing (8pt base):** ${inline(M.spacing)}`,
      `- **Radii:** ${inline(M.radii)}`,
      ...M.shadow.map(d => `- ${code(d.name)}: ${code(d.value)}`),
      `- **Motion:** ${inline(M.motion)}`,
      `- **Layout:** ${inline(M.layout)}`,
      `- **Dark theme** also overrides: ${M.dark.filter(d => d.group !== 'semantic').map(d => code(d.name)).join(', ')} (deeper shadows).`, '');
  }
  return parts.join('\n');
}

const TOKEN_BLOCK_RE = /<!-- tokens:start( variant=(\w+))? -->[\s\S]*?<!-- tokens:end -->/g;

function applyTokenBlocks(text, M, file) {
  let found = false;
  const out = text.replace(TOKEN_BLOCK_RE, (_, __, variant) => {
    found = true;
    return `<!-- tokens:start${variant ? ' variant=' + variant : ''} -->\n${mdTokensBlock(M, variant || 'full')}<!-- tokens:end -->`;
  });
  if (!found) throw new Error(`${file}: missing <!-- tokens:start --> … <!-- tokens:end --> markers`);
  return out;
}

// ============================================================
// Kit: CSS, SCSS, Tailwind, Figma
// ============================================================
function buildKitCss(M) {
  const extras = read('scripts/kit-extras.css');
  return [
    `@import url("${GOOGLE_FONTS}");`,
    '',
    '/* ============================================================',
    `   KILOWOTT BRAND KIT v${M.version} — kilowott.css (drop-in stylesheet)`,
    `   Link this ONE file to get on-brand pages:`,
    `     <link rel="stylesheet" href="${BASE_URL}/project/kit/kilowott.css">`,
    '   Contains: Google Fonts import, every token from tokens.css, base',
    '   reset, layout helpers, and the .btn / .chip / .card / .eyebrow /',
    '   .display primitives, plus kit additions (links, focus, logo, nav,',
    '   stat, sections, footer, Lucide icon sizing).',
    `   Docs: ${BASE_URL}/AGENTS.md`,
    `   ${GEN_NOTE}`,
    '   ============================================================ */',
    '',
    M.css.trim(),
    '',
    extras.trim(),
    '',
  ].join('\n');
}

function buildScss(M) {
  const v = n => '$' + n.slice(2);
  const val = (d, R) => {
    const raw = R.raw(d.name);
    const ref = refOf(raw);
    return ref ? v(ref) : raw;
  };
  const lines = [
    `// Kilowott brand kit v${M.version} — Sass tokens`,
    `// ${GEN_NOTE}`,
    `// Prefer the CSS custom properties (kilowott.css) at runtime; use these for build-time maths.`,
    '',
  ];
  const section = (title, list) => {
    lines.push(`// ---------- ${title} ----------`);
    list.forEach(d => lines.push(`${v(d.name)}: ${val(d, M.light)};${M.describe(d) ? ' // ' + M.describe(d) : ''}`));
    lines.push('');
  };
  section('Brand colours', M.brand);
  section('State colours (product UI only)', M.state);
  section('Semantic (light theme, default)', M.semantic);
  section('Type', M.type);
  section('Spacing (8pt)', M.spacing);
  section('Radii', M.radii);
  section('Shadows', M.shadow);
  section('Motion', M.motion);
  section('Layout', M.layout);
  const map = (name, list, R) => {
    lines.push(`${name}: (`);
    list.forEach(d => lines.push(`  "${shortName(d.name)}": ${val(d, R)},`));
    lines.push(');', '');
  };
  map('$kilowott-brand', M.brand, M.light);
  map('$kilowott-state', M.state, M.light);
  map('$kilowott-theme-light', M.semantic, M.light);
  map('$kilowott-theme-dark', M.semantic, M.darkR);
  map('$kilowott-spacing', M.spacing, M.light);
  return lines.join('\n');
}

function buildTailwind3(M) {
  const hex = n => normHex(M.light.get(n));
  const obj = list => Object.fromEntries(list.map(d => [shortName(d.name), hex(d.name)]));
  const sem = Object.fromEntries(M.semantic.map(d => {
    const r = M.light.get(d.name);
    return [shortName(d.name), `var(${d.name}, ${isHex(r) ? normHex(r) : r})`];
  }));
  const pick = (prefix, list) => Object.fromEntries(list.filter(d => d.name.startsWith(prefix)).map(d => [d.name.slice(prefix.length), d.value]));
  const theme = {
    colors: { k: { ...obj(M.brand), ...obj(M.state) }, ...sem },
    fontFamily: Object.fromEntries(M.type.filter(d => d.name.startsWith('--font-')).map(d => [d.name.slice(7), parseFontStack(d.value)])),
    fontSize: pick('--fs-', M.type),
    lineHeight: pick('--lh-', M.type),
    letterSpacing: pick('--tracking-', M.type),
    spacing: Object.fromEntries(M.spacing.map(d => [shortName(d.name), d.value === '0' ? '0px' : d.value])),
    borderRadius: Object.fromEntries(M.radii.map(d => [shortName(d.name), d.value === '0' ? '0px' : d.value])),
    boxShadow: Object.fromEntries(M.shadow.map(d => ['k-' + d.name.replace('--shadow-', ''), d.value])),
    transitionTimingFunction: pick('--ease-', M.motion),
    transitionDuration: pick('--dur-', M.motion),
    maxWidth: { container: M.light.get('--container') },
  };
  return [
    `/* Kilowott brand kit v${M.version} — Tailwind CSS v3 preset`,
    `   ${GEN_NOTE}`,
    '   Usage (tailwind.config.js):',
    `     module.exports = { presets: [require('./tokens.tailwind.js')], content: [...] }`,
    `   Download: ${BASE_URL}/project/kit/tokens.tailwind.js`,
    '   Brand hex lives under `k-*` (bg-k-paper, text-k-ink, border-k-rule-soft).',
    '   Semantic colours read the CSS variables from kilowott.css with hex fallbacks',
    '   (bg-bg, text-fg, text-fg-2, border-rule, text-link, bg-accent) so dark theme works.',
    '   Spacing keys are prefixed (p-s-5 = 24px) so Tailwind defaults stay intact.',
    '   Red is one spotlight per surface: use bg-accent / text-accent once. */',
    '',
    'module.exports = {',
    '  theme: {',
    '    extend: ' + JSON.stringify(theme, null, 2).replace(/\n/g, '\n    ') + ',',
    '  },',
    '};',
    '',
  ].join('\n');
}

function buildTailwind4(M) {
  const lines = [
    `/* Kilowott brand kit v${M.version} — Tailwind CSS v4 theme`,
    `   ${GEN_NOTE}`,
    '   Usage (your main CSS file):',
    '     @import "tailwindcss";',
    `     @import "${BASE_URL}/project/kit/kilowott.css";   (tokens + base + primitives)`,
    `     @import "${BASE_URL}/project/kit/tokens.tailwind.css";`,
    '   Then: bg-k-paper, text-k-ink, bg-bg, text-fg, text-fg-2, border-rule, text-link,',
    '   font-display, font-sans, font-mono, text-d1/d2/d3, shadow-k-2, rounded-pill. */',
    '',
    '@theme inline {',
  ];
  [...M.brand, ...M.state].forEach(d => lines.push(`  --color-k-${shortName(d.name)}: ${normHex(M.light.get(d.name))};`));
  M.semantic.forEach(d => {
    const r = M.light.get(d.name);
    lines.push(`  --color-${shortName(d.name)}: var(${d.name}, ${isHex(r) ? normHex(r) : r});`);
  });
  M.type.filter(d => d.name.startsWith('--font-')).forEach(d => lines.push(`  ${d.name}: ${d.value};`));
  M.type.filter(d => d.name.startsWith('--fs-')).forEach(d => lines.push(`  --text-${d.name.slice(5)}: ${d.value};`));
  M.type.filter(d => d.name.startsWith('--lh-')).forEach(d => lines.push(`  --leading-${d.name.slice(5)}: ${d.value};`));
  M.type.filter(d => d.name.startsWith('--tracking-')).forEach(d => lines.push(`  --tracking-${d.name.slice(11)}: ${d.value};`));
  M.radii.forEach(d => lines.push(`  --radius-${d.name.slice(4)}: ${d.value === '0' ? '0px' : d.value};`));
  M.shadow.forEach(d => lines.push(`  --shadow-k-${d.name.slice(9)}: ${d.value};`));
  M.motion.filter(d => d.name.startsWith('--ease-')).forEach(d => lines.push(`  --ease-k-${d.name.slice(7)}: ${d.value};`));
  lines.push(`  --container-k: ${M.light.get('--container')};`, '}', '');
  return lines.join('\n');
}

function buildFigma(M) {
  const ref = (d, R) => {
    const raw = R.raw(d.name);
    const r = refOf(raw);
    if (r) {
      const t = M.root.find(x => x.name === r);
      if (t && t.group === 'semantic') return `{semantic.${shortName(r)}}`;
      if (t) return `{${t.path.join('.')}}`;
    }
    return isHex(raw) ? normHex(raw) : raw;
  };
  const color = list => Object.fromEntries(list.map(d => [shortName(d.name), { value: normHex(M.light.get(d.name)), type: 'color', description: M.describe(d) || '' }]));
  const global = {
    color: { brand: color(M.brand), state: color(M.state) },
    fontFamilies: Object.fromEntries(M.type.filter(d => d.name.startsWith('--font-')).map(d => [d.name.slice(7), { value: parseFontStack(d.value)[0], type: 'fontFamilies', description: d.value }])),
    fontSizes: Object.fromEntries(M.type.filter(d => d.name.startsWith('--fs-')).map(d => {
      const range = clampPx(d.value), px = remToPx(d.value);
      return [d.name.slice(5), { value: String(range ? range[1] : px), type: 'fontSizes', description: range ? `fluid ${range[0]}–${range[1]}px (${d.value}); value = desktop max` : d.value }];
    })),
    lineHeights: Object.fromEntries(M.type.filter(d => d.name.startsWith('--lh-')).map(d => [d.name.slice(5), { value: Math.round(parseFloat(d.value) * 100) + '%', type: 'lineHeights' }])),
    letterSpacing: Object.fromEntries(M.type.filter(d => d.name.startsWith('--tracking-')).map(d => [d.name.slice(11), { value: Math.round(parseFloat(d.value) * 100) + '%', type: 'letterSpacing' }])),
    fontWeights: { regular: { value: '400', type: 'fontWeights' }, medium: { value: '500', type: 'fontWeights' } },
    spacing: Object.fromEntries(M.spacing.map(d => [shortName(d.name), { value: String(parseFloat(d.value) || 0), type: 'spacing' }])),
    borderRadius: Object.fromEntries(M.radii.map(d => [shortName(d.name), { value: String(parseFloat(d.value) || 0), type: 'borderRadius' }])),
    boxShadow: Object.fromEntries(M.shadow.map(d => [d.name.replace('--shadow-', ''), {
      value: parseShadow(d.value).map(l => ({ x: String(parseFloat(l.offsetX)), y: String(parseFloat(l.offsetY)), blur: String(parseFloat(l.blur)), spread: String(parseFloat(l.spread)), color: l.color, type: 'dropShadow' })),
      type: 'boxShadow',
    }])),
  };
  const themeSet = R => ({ semantic: Object.fromEntries(M.semantic.map(d => [shortName(d.name), { value: ref(d, R), type: 'color', description: SEMANTIC_ROLES[shortName(d.name)] || '' }])) });
  return JSON.stringify({
    global,
    light: themeSet(M.light),
    dark: themeSet(M.darkR),
    $themes: [
      { id: 'kilowott-light', name: 'Kilowott light (default)', selectedTokenSets: { global: 'source', light: 'enabled' } },
      { id: 'kilowott-dark', name: 'Kilowott dark', selectedTokenSets: { global: 'source', dark: 'enabled' } },
    ],
    $metadata: { tokenSetOrder: ['global', 'light', 'dark'], generatedBy: 'scripts/build-tokens.mjs', version: M.version },
  }, null, 2) + '\n';
}

// ============================================================
// Downloads: swatches + logo
// ============================================================
function swatches(M) {
  const title = d => shortName(d.name).split('-').map((w, i) => (i === 0 ? w[0].toUpperCase() + w.slice(1) : w)).join(' ');
  const mk = (list, group) => list.map(d => {
    const hex = normHex(M.light.get(d.name));
    return { name: `Kilowott ${title(d)}`, token: d.name, hex, rgb: hexToRgb(hex), role: M.describe(d) || '', group };
  });
  return [...mk(M.brand, 'Kilowott brand'), ...mk(M.state, 'Kilowott state (product UI only)')];
}

function aseString(s) {
  const b = Buffer.alloc(2 + (s.length + 1) * 2);
  b.writeUInt16BE(s.length + 1, 0);
  for (let i = 0; i < s.length; i++) b.writeUInt16BE(s.charCodeAt(i), 2 + i * 2);
  return b;
}
function aseBlock(type, body) {
  const h = Buffer.alloc(6);
  h.writeUInt16BE(type, 0);
  h.writeUInt32BE(body.length, 2);
  return Buffer.concat([h, body]);
}
function buildAse(M) {
  const list = swatches(M);
  const blocks = [];
  for (const group of [...new Set(list.map(s => s.group))]) {
    blocks.push(aseBlock(0xC001, aseString(group)));
    list.filter(s => s.group === group).forEach(s => {
      const vals = Buffer.alloc(12);
      s.rgb.forEach((v, i) => vals.writeFloatBE(v / 255, i * 4));
      const type = Buffer.alloc(2); type.writeUInt16BE(0, 0); // 0 = global
      blocks.push(aseBlock(0x0001, Buffer.concat([aseString(`${s.name} ${s.hex}`), Buffer.from('RGB ', 'ascii'), vals, type])));
    });
    blocks.push(aseBlock(0xC002, Buffer.alloc(0)));
  }
  const head = Buffer.alloc(12);
  head.write('ASEF', 0, 'ascii');
  head.writeUInt16BE(1, 4); head.writeUInt16BE(0, 6);
  head.writeUInt32BE(blocks.length, 8);
  return Buffer.concat([head, ...blocks]);
}
function buildGpl(M) {
  return ['GIMP Palette', `Name: Kilowott ${M.version}`, 'Columns: 4',
    `# ${GEN_NOTE}`, '# 60·30·5·5 = paper · ink · warm paper · red. Red is one spotlight per surface.',
    ...swatches(M).map(s => `${s.rgb.map(v => String(v).padStart(3)).join(' ')}\t${s.name} (${s.token}) ${s.hex}`), ''].join('\n');
}
function buildSwatchJson(M) {
  return JSON.stringify({
    name: 'Kilowott colours', version: M.version, _generated: GEN_NOTE,
    usage_ratio: '60·30·5·5 = paper · ink · warm paper · red',
    colors: swatches(M),
  }, null, 2) + '\n';
}

// ============================================================
// llms-full.txt
// ============================================================
function buildLlmsFull(M, docs) {
  let firstFull = true;
  // Keep compact blocks and the first full block; later full blocks are duplicates.
  const strip = (text) => text.replace(TOKEN_BLOCK_RE, (block, _, variant) => {
    if (variant) return block;
    if (firstFull) { firstFull = false; return block; }
    return '(Token tables: identical to the full tables in the KILOWOTT_BRAND.md section above.)';
  });
  const sources = [
    ['AGENTS.md', 'Agent guide: decision tree, rules, files, page index, starter page'],
    ['KILOWOTT_BRAND.md', 'Brand reference: principles, tokens, type, logo, imagery, voice'],
    ['project/llms.txt', 'Build spec: render recipe, component and pattern specs, facts'],
  ];
  // Put the full token block first: brand reference before agent guide would also work,
  // but agents should meet the decision tree first, so only strip compact duplicates.
  const out = [
    `# Kilowott brand kit v${M.version} — full reference for AI agents`,
    '',
    `> Everything an agent needs in one file. Concatenation of ${sources.map(s => s[0]).join(', ')}.`,
    `> Live kit: ${BASE_URL}/project/ · Index: ${BASE_URL}/llms.txt · ${GEN_NOTE}`,
    '',
  ];
  sources.forEach(([file, label]) => {
    out.push('', '='.repeat(72), `FILE: ${BASE_URL}/${file}`, `(${label})`, '='.repeat(72), '', strip(docs[file]).trim(), '');
  });
  return out.join('\n');
}

// ============================================================
// BUILD ALL (in memory)
// ============================================================
export const TOKEN_DOCS = ['llms.txt', 'project/llms.txt', 'KILOWOTT_BRAND.md', 'AGENTS.md'];

export function buildAll() {
  const M = loadModel();
  const files = new Map();
  files.set('tokens.json', buildTokensJson(M));
  files.set('project/brand.json', buildBrandJson(M));
  const docs = {};
  TOKEN_DOCS.forEach(f => { docs[f] = applyTokenBlocks(read(f), M, f); files.set(f, docs[f]); });
  files.set('llms-full.txt', buildLlmsFull(M, docs));
  files.set('project/kit/kilowott.css', buildKitCss(M));
  files.set('project/kit/tokens.scss', buildScss(M));
  files.set('project/kit/tokens.tailwind.js', buildTailwind3(M));
  files.set('project/kit/tokens.tailwind.css', buildTailwind4(M));
  files.set('project/kit/figma-tokens.json', buildFigma(M));
  files.set('project/downloads/kilowott-colors.ase', buildAse(M));
  files.set('project/downloads/kilowott-colors.gpl', buildGpl(M));
  files.set('project/downloads/kilowott-colors.json', buildSwatchJson(M));
  const logoSvg = fs.readFileSync(path.join(ROOT, 'project/assets/kilowott-logo.svg'), 'utf8');
  const logoNavy = normHex(M.light.get('--k-navy'));
  if (!logoSvg.includes(`fill="${logoNavy}"`)) throw new Error(`project/assets/kilowott-logo.svg must be filled with --k-navy (${logoNavy})`);
  files.set('project/downloads/kilowott-logo.svg', logoSvg);
  files.set('project/downloads/logo/kilowott-logo-navy.svg', logoSvg);
  files.set('project/downloads/logo/kilowott-logo-white.svg', logoSvg.replace(`fill="${logoNavy}"`, 'fill="#FFFFFF"'));
  files.set('project/downloads/logo/kilowott-logo-black.svg', logoSvg.replace(`fill="${logoNavy}"`, 'fill="#000000"'));
  return { files, model: M };
}

export function diffAgainstDisk(files) {
  const stale = [];
  for (const [rel, content] of files) {
    const abs = path.join(ROOT, rel);
    const want = Buffer.isBuffer(content) ? content : Buffer.from(content, 'utf8');
    if (!fs.existsSync(abs) || !fs.readFileSync(abs).equals(want)) stale.push(rel);
  }
  return stale;
}

// ---------- CLI ----------
if (import.meta.url === pathToFileURL(process.argv[1]).href) {
  const dry = process.argv.includes('--dry');
  const { files } = buildAll();
  const stale = diffAgainstDisk(files);
  if (!stale.length) { console.log('build:tokens — all generated files already up to date.'); process.exit(0); }
  for (const rel of stale) {
    if (dry) { console.log('would write', rel); continue; }
    const abs = path.join(ROOT, rel);
    fs.mkdirSync(path.dirname(abs), { recursive: true });
    fs.writeFileSync(abs, files.get(rel));
    console.log('wrote', rel);
  }
}
